assert len(items)==100, len(items)
assert len({(item['stem'],item['code']) for item in items})==100
assert len({item['title'] for item in items})==100
# Rotate answer positions deterministically; keep the original explanations intact.
rng=random.Random(4710)
for item in items:
    order=list(range(4));rng.shuffle(order)
    item['options']=[item['options'][i] for i in order]
    item['correct']=sorted(order.index(i) for i in item['correct'])
    assert item['correct'] and all(0<=i<4 for i in item['correct'])
root=Path(__file__).resolve().parent
(root/'questions.json').write_text(json.dumps(items,indent=2,ensure_ascii=False)+'\n')
print(f"Authored {len(items)} questions; {sum(bool(x['code']) for x in items)} include Python; {sum(len(x['correct'])>1 for x in items)} select-all questions.")
